/**
 * Technical-analysis indicators. Pure functions: inputs are never mutated and every output array is aligned 1:1
 * with the input (same length, same index = same bar). `null` marks warm-up / undefined values.
 *
 * Where TA-Lib has the function (SMA, EMA, RSI, ATR, TRANGE, MACD, BBANDS, ADX, PLUS_DI, MINUS_DI) the output
 * matches TA-Lib's defaults, including its warm-up length and seeding quirks; this is verified against golden
 * fixtures generated by TA-Lib (tests/fixtures/gen/gen_indicators.py).
 *
 * Inputs are expected to be finite numbers. A non-finite value poisons every output whose window contains it
 * (rolling functions return null there; recursive functions such as EMA/RSI/ATR/ADX propagate it).
 */

import type { Series } from './types';

function checkPeriod(period: number, name = 'period', min = 1): void {
  if (!Number.isInteger(period) || period < min) {
    throw new RangeError(`${name} must be an integer >= ${min}, got ${period}`);
  }
}

function nulls(n: number): Series {
  return new Array<number | null>(n).fill(null);
}

function finiteOrNull(x: number): number | null {
  return Number.isFinite(x) ? x : null;
}

// ---------------------------------------------------------------------------------------------------------------
// Rolling windows
// ---------------------------------------------------------------------------------------------------------------

/** Rolling arithmetic mean of the last `period` values (including the current one). First value at index period-1. */
export function rollingMean(values: readonly number[], period: number): Series {
  checkPeriod(period);
  const out = nulls(values.length);
  for (let i = period - 1; i < values.length; i++) {
    let sum = 0;
    for (let j = i - period + 1; j <= i; j++) sum += values[j]!;
    out[i] = finiteOrNull(sum / period);
  }
  return out;
}

/** Rolling minimum of the last `period` values (including the current one). First value at index period-1. */
export function rollingMin(values: readonly number[], period: number): Series {
  checkPeriod(period);
  const out = nulls(values.length);
  for (let i = period - 1; i < values.length; i++) {
    let m = Number.POSITIVE_INFINITY;
    for (let j = i - period + 1; j <= i; j++) {
      const v = values[j]!;
      if (Number.isNaN(v)) {
        m = Number.NaN;
        break;
      }
      if (v < m) m = v;
    }
    out[i] = finiteOrNull(m);
  }
  return out;
}

/** Rolling maximum of the last `period` values (including the current one). First value at index period-1. */
export function rollingMax(values: readonly number[], period: number): Series {
  checkPeriod(period);
  const out = nulls(values.length);
  for (let i = period - 1; i < values.length; i++) {
    let m = Number.NEGATIVE_INFINITY;
    for (let j = i - period + 1; j <= i; j++) {
      const v = values[j]!;
      if (Number.isNaN(v)) {
        m = Number.NaN;
        break;
      }
      if (v > m) m = v;
    }
    out[i] = finiteOrNull(m);
  }
  return out;
}

/** Simple return over `lag` bars: values[i] / values[i - lag] - 1. Null for i < lag or a zero base. */
export function pctChange(values: readonly number[], lag: number): Series {
  checkPeriod(lag, 'lag');
  const out = nulls(values.length);
  for (let i = lag; i < values.length; i++) {
    const base = values[i - lag]!;
    out[i] = base === 0 ? null : finiteOrNull(values[i]! / base - 1);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Moving averages
// ---------------------------------------------------------------------------------------------------------------

/** Simple moving average (TA-Lib SMA). First value at index period-1. */
export function sma(values: readonly number[], period: number): Series {
  return rollingMean(values, period);
}

/**
 * Exponential moving average (TA-Lib EMA): alpha = 2 / (period + 1), seeded at index period-1 with the SMA of the
 * first `period` values; null before that.
 */
export function ema(values: readonly number[], period: number): Series {
  checkPeriod(period);
  const out = nulls(values.length);
  if (values.length < period) return out;
  const alpha = 2 / (period + 1);
  let seed = 0;
  for (let i = 0; i < period; i++) seed += values[i]!;
  let prev = seed / period;
  out[period - 1] = finiteOrNull(prev);
  for (let i = period; i < values.length; i++) {
    prev = prev + alpha * (values[i]! - prev);
    out[i] = finiteOrNull(prev);
  }
  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Momentum / trend
// ---------------------------------------------------------------------------------------------------------------

/**
 * Relative Strength Index (TA-Lib RSI, Wilder smoothing). First value at index `period`: the average gain/loss
 * are seeded with the simple mean of the first `period` changes, then smoothed as (prev * (period - 1) + x) / period.
 * TA-Lib quirk preserved: when the average gain and loss are both exactly zero (completely flat window) RSI is 0.
 */
export function rsi(closes: readonly number[], period = 14): Series {
  checkPeriod(period);
  const n = closes.length;
  const out = nulls(n);
  if (n <= period) return out;
  let avgGain = 0;
  let avgLoss = 0;
  for (let i = 1; i <= period; i++) {
    const d = closes[i]! - closes[i - 1]!;
    if (d > 0) avgGain += d;
    else avgLoss -= d;
  }
  avgGain /= period;
  avgLoss /= period;
  const toRsi = (g: number, l: number): number => (g + l === 0 ? 0 : (100 * g) / (g + l));
  out[period] = finiteOrNull(toRsi(avgGain, avgLoss));
  for (let i = period + 1; i < n; i++) {
    const d = closes[i]! - closes[i - 1]!;
    const gain = d > 0 ? d : 0;
    const loss = d < 0 ? -d : 0;
    avgGain = (avgGain * (period - 1) + gain) / period;
    avgLoss = (avgLoss * (period - 1) + loss) / period;
    out[i] = finiteOrNull(toRsi(avgGain, avgLoss));
  }
  return out;
}

/** True range (TA-Lib TRANGE): max(high, prevClose) - min(low, prevClose). Index 0 is null (no previous close). */
export function trueRange(high: readonly number[], low: readonly number[], close: readonly number[]): Series {
  const n = close.length;
  const out = nulls(n);
  for (let i = 1; i < n; i++) {
    const pc = close[i - 1]!;
    out[i] = finiteOrNull(Math.max(high[i]!, pc) - Math.min(low[i]!, pc));
  }
  return out;
}

/** Raw (non-null) true range for indexes >= 1; index 0 holds NaN. Internal helper. */
function rawTrueRange(high: readonly number[], low: readonly number[], close: readonly number[]): number[] {
  const n = close.length;
  const tr = new Array<number>(n).fill(Number.NaN);
  for (let i = 1; i < n; i++) {
    const pc = close[i - 1]!;
    tr[i] = Math.max(high[i]!, pc) - Math.min(low[i]!, pc);
  }
  return tr;
}

/**
 * Average True Range (TA-Lib ATR, Wilder smoothing). First value at index `period`: the simple mean of
 * TR[1..period], then ATR[i] = (ATR[i-1] * (period - 1) + TR[i]) / period.
 */
export function atr(high: readonly number[], low: readonly number[], close: readonly number[], period = 14): Series {
  checkPeriod(period);
  const n = close.length;
  const out = nulls(n);
  if (n <= period) return out;
  const tr = rawTrueRange(high, low, close);
  let prev = 0;
  for (let i = 1; i <= period; i++) prev += tr[i]!;
  prev /= period;
  out[period] = finiteOrNull(prev);
  for (let i = period + 1; i < n; i++) {
    prev = (prev * (period - 1) + tr[i]!) / period;
    out[i] = finiteOrNull(prev);
  }
  return out;
}

export interface MacdResult {
  macd: Series;
  signal: Series;
  hist: Series;
}

/**
 * MACD (TA-Lib MACD): macd = EMA(fast) - EMA(slow), signal = EMA(macd, signal), hist = macd - signal.
 *
 * TA-Lib specifics replicated here (verified against the golden fixture):
 *  - both EMAs are computed from index slow-1 onwards; the fast EMA is seeded with the SMA of the `fast` closes
 *    ENDING at index slow-1 (not the properly warmed EMA that would have started at index fast-1);
 *  - the signal EMA is seeded with the SMA of the first `signal` macd values (indexes slow-1 .. slow+signal-2);
 *  - all three outputs are only reported from index slow+signal-2 (33 for 12/26/9), so the macd line is null
 *    during the signal warm-up even though it could be computed earlier.
 * If fast > slow the two are swapped, as TA-Lib does.
 */
export function macd(closes: readonly number[], fast = 12, slow = 26, signal = 9): MacdResult {
  checkPeriod(fast);
  checkPeriod(slow);
  checkPeriod(signal);
  if (fast > slow) [fast, slow] = [slow, fast];
  const n = closes.length;
  const out: MacdResult = { macd: nulls(n), signal: nulls(n), hist: nulls(n) };
  const first = slow - 1; // first index where both EMAs exist
  const firstOut = first + signal - 1; // first index where macd/signal/hist are reported
  if (n <= firstOut) return out;

  const kFast = 2 / (fast + 1);
  const kSlow = 2 / (slow + 1);
  const kSig = 2 / (signal + 1);

  let fastEma = 0;
  for (let i = first - fast + 1; i <= first; i++) fastEma += closes[i]!;
  fastEma /= fast;
  let slowEma = 0;
  for (let i = 0; i <= first; i++) slowEma += closes[i]!;
  slowEma /= slow;

  const diff = new Array<number>(n).fill(Number.NaN);
  diff[first] = fastEma - slowEma;
  for (let i = first + 1; i < n; i++) {
    fastEma += kFast * (closes[i]! - fastEma);
    slowEma += kSlow * (closes[i]! - slowEma);
    diff[i] = fastEma - slowEma;
  }

  let sig = 0;
  for (let i = first; i <= firstOut; i++) sig += diff[i]!;
  sig /= signal;
  out.macd[firstOut] = finiteOrNull(diff[firstOut]!);
  out.signal[firstOut] = finiteOrNull(sig);
  out.hist[firstOut] = finiteOrNull(diff[firstOut]! - sig);
  for (let i = firstOut + 1; i < n; i++) {
    sig += kSig * (diff[i]! - sig);
    out.macd[i] = finiteOrNull(diff[i]!);
    out.signal[i] = finiteOrNull(sig);
    out.hist[i] = finiteOrNull(diff[i]! - sig);
  }
  return out;
}

export interface BollingerResult {
  upper: Series;
  middle: Series;
  lower: Series;
}

/**
 * Bollinger Bands (TA-Lib BBANDS with SMA): middle = SMA(period), bands = middle +/- k * population standard
 * deviation (divisor n, as TA-Lib). First value at index period-1.
 */
export function bollinger(closes: readonly number[], period = 20, k = 2): BollingerResult {
  checkPeriod(period);
  const n = closes.length;
  const out: BollingerResult = { upper: nulls(n), middle: nulls(n), lower: nulls(n) };
  for (let i = period - 1; i < n; i++) {
    let sum = 0;
    for (let j = i - period + 1; j <= i; j++) sum += closes[j]!;
    const mid = sum / period;
    let ss = 0;
    for (let j = i - period + 1; j <= i; j++) ss += (closes[j]! - mid) * (closes[j]! - mid);
    const sd = Math.sqrt(ss / period);
    out.middle[i] = finiteOrNull(mid);
    out.upper[i] = finiteOrNull(mid + k * sd);
    out.lower[i] = finiteOrNull(mid - k * sd);
  }
  return out;
}

export interface AdxResult {
  adx: Series;
  plusDi: Series;
  minusDi: Series;
}

/**
 * ADX, +DI and -DI (TA-Lib ADX / PLUS_DI / MINUS_DI), Wilder smoothing in TA-Lib's "sum" form:
 * the smoothed value S is initialised as the plain sum of the first period-1 directional movements / true ranges
 * (bars 1 .. period-1), then S = S - S / period + x. +DI/-DI = 100 * smoothedDM / smoothedTR, first value at
 * index `period`. ADX is the Wilder average of DX = 100 * |+DI - -DI| / (+DI + -DI): seeded with the mean of the
 * first `period` DX values, so its first value is at index 2 * period - 1.
 */
export function adx(high: readonly number[], low: readonly number[], close: readonly number[], period = 14): AdxResult {
  checkPeriod(period);
  const n = close.length;
  const out: AdxResult = { adx: nulls(n), plusDi: nulls(n), minusDi: nulls(n) };
  if (n <= period) return out;

  const dm = (i: number): { plus: number; minus: number; tr: number } => {
    const up = high[i]! - high[i - 1]!;
    const down = low[i - 1]! - low[i]!;
    const pc = close[i - 1]!;
    return {
      plus: up > 0 && up > down ? up : 0,
      minus: down > 0 && up < down ? down : 0,
      tr: Math.max(high[i]!, pc) - Math.min(low[i]!, pc),
    };
  };

  let sPlus = 0;
  let sMinus = 0;
  let sTr = 0;
  for (let i = 1; i < period; i++) {
    const d = dm(i);
    sPlus += d.plus;
    sMinus += d.minus;
    sTr += d.tr;
  }

  let sumDx = 0;
  let prevAdx = 0;
  for (let i = period; i < n; i++) {
    const d = dm(i);
    sPlus = sPlus - sPlus / period + d.plus;
    sMinus = sMinus - sMinus / period + d.minus;
    sTr = sTr - sTr / period + d.tr;

    let plusDi = 0;
    let minusDi = 0;
    let dx = 0;
    if (sTr !== 0) {
      plusDi = (100 * sPlus) / sTr;
      minusDi = (100 * sMinus) / sTr;
      const total = plusDi + minusDi;
      if (total !== 0) dx = (100 * Math.abs(minusDi - plusDi)) / total;
    }
    out.plusDi[i] = finiteOrNull(plusDi);
    out.minusDi[i] = finiteOrNull(minusDi);

    if (i < 2 * period - 1) {
      sumDx += dx;
    } else if (i === 2 * period - 1) {
      sumDx += dx;
      prevAdx = sumDx / period;
      out.adx[i] = finiteOrNull(prevAdx);
    } else {
      prevAdx = (prevAdx * (period - 1) + dx) / period;
      out.adx[i] = finiteOrNull(prevAdx);
    }
  }
  return out;
}

// ---------------------------------------------------------------------------------------------------------------
// Price structure
// ---------------------------------------------------------------------------------------------------------------

export interface DonchianResult {
  upper: Series;
  lower: Series;
}

/**
 * Donchian channel: upper = highest high, lower = lowest low over the last `period` bars INCLUDING the current
 * bar. First value at index period-1. (Compare today's close with the previous bar's channel for a breakout test.)
 */
export function donchian(high: readonly number[], low: readonly number[], period: number): DonchianResult {
  return { upper: rollingMax(high, period), lower: rollingMin(low, period) };
}

/**
 * 5-bar fractal lows. At index i (needs i-2 .. i+2) the value is low[i] if low[i] is STRICTLY lower than
 * low[i-1], low[i-2], low[i+1] and low[i+2]; otherwise null. A fractal is only confirmed two bars later, so the
 * last two indexes are always null and callers must not read them as "no fractal yet": ignore them.
 */
export function fractalLows(low: readonly number[]): Series {
  const n = low.length;
  const out = nulls(n);
  for (let i = 2; i < n - 2; i++) {
    const v = low[i]!;
    if (v < low[i - 1]! && v < low[i - 2]! && v < low[i + 1]! && v < low[i + 2]!) out[i] = v;
  }
  return out;
}

/**
 * 5-bar fractal highs, the mirror of `fractalLows`: the value at index i is high[i] when it is STRICTLY higher than the two
 * bars on either side; otherwise null. Confirmed two bars late, so the last two indexes are always null.
 */
export function fractalHighs(high: readonly number[]): Series {
  const n = high.length;
  const out = nulls(n);
  for (let i = 2; i < n - 2; i++) {
    const v = high[i]!;
    if (v > high[i - 1]! && v > high[i - 2]! && v > high[i + 1]! && v > high[i + 2]!) out[i] = v;
  }
  return out;
}

/**
 * Anchored VWAP: the volume-weighted average of the typical price (high + low + close) / 3 from bar `anchorIndex` to each
 * later bar, cumulative. Null before the anchor and wherever the cumulative volume is still zero. An anchor outside the
 * input (negative or past the last bar) gives all nulls; a non-integer anchor is a RangeError.
 */
export function avwap(
  high: readonly number[],
  low: readonly number[],
  close: readonly number[],
  volume: readonly number[],
  anchorIndex: number,
): Series {
  if (!Number.isInteger(anchorIndex)) throw new RangeError(`anchorIndex must be an integer, got ${anchorIndex}`);
  const n = close.length;
  const out = nulls(n);
  if (anchorIndex < 0 || anchorIndex >= n) return out;
  let pv = 0;
  let vv = 0;
  for (let i = anchorIndex; i < n; i++) {
    const typical = (high[i]! + low[i]! + close[i]!) / 3;
    pv += typical * volume[i]!;
    vv += volume[i]!;
    out[i] = vv > 0 ? finiteOrNull(pv / vv) : null;
  }
  return out;
}

/**
 * Gap-ups that are still open at the last bar. A bar i gaps up when its low is above the previous bar's high; the gap
 * stays unfilled while no later low has traded down to that previous high. The value at i is the top of the gap (low[i]),
 * the level that acts as support; the bottom of the gap is high[i - 1]. Only the last `lookback` bars are examined; every
 * other index is null.
 */
export function unfilledGapUps(high: readonly number[], low: readonly number[], lookback: number): Series {
  checkPeriod(lookback, 'lookback');
  const n = low.length;
  const out = nulls(n);
  for (let i = Math.max(1, n - lookback); i < n; i++) {
    const bottom = high[i - 1]!;
    if (!(low[i]! > bottom)) continue;
    let filled = false;
    for (let j = i + 1; j < n; j++) {
      if (low[j]! <= bottom) {
        filled = true;
        break;
      }
    }
    if (!filled) out[i] = finiteOrNull(low[i]!);
  }
  return out;
}
